class Grid {
  constructor(tile_size, width, height, number_of_types) {
    //create the grid
		this.grid = [];
		var index = 0;
		for(var y = 0; y < height; y += (Math.max(0.001, Math.abs(tile_size)) || 1)) {
			this.itensPerRow = 0;
			for(var x = 0; x < width; x += (Math.max(0.001, Math.abs(tile_size)) || 1)) {
				this.itensPerRow++;
				this.grid.push({
					x, y, index,
					number: values ? values[index] : floor(random(number_of_types)),
					used: false//to find neighbors
				})
				index++;
			}
		}

		//group itens by same number type
		var groups = [];
		this.grid.forEach((g, index) => {
			if(!g.used){
				var neighbors = [];
				this.findNeighbors(g.number, index, neighbors);
				neighbors.number = g.number;
				groups.push(neighbors);
			}
		});

		//create shape with perimeter coordinates
		this.shapes = [];
		groups.forEach(group => {
			//convert group of squares to countour shape
			//idea adapted from: https://stackoverflow.com/questions/20997254/java-merge-adiacent-rectangles-into-a-polygon?rq=1

			//created edges
			var edges = [];
			group.forEach(g => {
				edges.push({x1: g.x, y1: g.y, x2: g.x + tile_size, y2: g.y});//top
				edges.push({x1: g.x + tile_size, y1: g.y, x2: g.x + tile_size, y2: g.y + tile_size});//left
				edges.push({x1: g.x + tile_size, y1: g.y + tile_size, x2: g.x, y2: g.y + tile_size});//bottom
				edges.push({x1: g.x, y1: g.y + tile_size, x2: g.x, y2: g.y});//right
			});

			//remove duplicated edges
			for(var i = edges.length-1; i >= 0; i--){
				const edge = edges[i];
				if(edge){
					const duplicatedIndex = edges.findIndex((edge2, i2) => 
						i !== i2 &&
						((edge.x1 === edge2.x1 && edge.y1 === edge2.y1 && edge.x2 === edge2.x2 && edge.y2 === edge2.y2) ||
						 (edge.x1 === edge2.x2 && edge.y1 === edge2.y2 && edge.x2 === edge2.x1 && edge.y2 === edge2.y1))
					);
					if(duplicatedIndex >= 0){
						edges.splice(Math.max(i, duplicatedIndex), 1);
						edges.splice(Math.min(i, duplicatedIndex), 1);
					}
				}
			}

			//connect edges
			var startEdge = edges.splice(0, 1)[0];
			var shape = [{x: startEdge.x1, y: startEdge.y1}];
			this.createShapeFromEdges(shape, edges, startEdge.x2, startEdge.y2);
			shape.number = group.number;

			this.shapes.push(shape);
		})

		//keep only corners vertex
		this.shapes = this.shapes.map(shape => this.keepCorners(shape));
  }

	keepCorners(vertices) {
			const result = [];
			for (let i = 0; i < vertices.length; i++) {
					const currentPoint = vertices[i];
					const prevPoint = vertices[(i - 1 + vertices.length) % vertices.length];
					const nextPoint = vertices[(i + 1) % vertices.length];

					const xChange = (currentPoint.x !== prevPoint.x || currentPoint.x !== nextPoint.x);
					const yChange = (currentPoint.y !== prevPoint.y || currentPoint.y !== nextPoint.y);
					if(xChange && yChange){
							result.push(currentPoint);
					}
			}
			result.number = vertices.number;
			return result;
	}

	shrinkPolygon(polygon, distance) {
			const shrinkedPolygon = [];

			for (let i = 0; i < polygon.length; i++) {
					const p1 = polygon[i];
					const p2 = polygon[(i + 1) % polygon.length];
					const p3 = polygon[(i + 2) % polygon.length];

					const dx1 = p2.x - p1.x;
					const dy1 = p2.y - p1.y;
					const length1 = Math.sqrt(dx1 * dx1 + dy1 * dy1);
					const nx1 = -dy1 / length1;
					const ny1 = dx1 / length1;

					const dx2 = p3.x - p2.x;
					const dy2 = p3.y - p2.y;
					const length2 = Math.sqrt(dx2 * dx2 + dy2 * dy2);
					const nx2 = -dy2 / length2;
					const ny2 = dx2 / length2;

					const miterX = p2.x + nx1 + nx2;
					const miterY = p2.y + ny1 + ny2;

					const miterLength = distance / Math.sqrt((nx1 + nx2) ** 2 + (ny1 + ny2) ** 2);

					const offsetX = miterLength * (nx1 + nx2);
					const offsetY = miterLength * (ny1 + ny2);

					const newX = miterX + offsetX;
					const newY = miterY + offsetY;

					shrinkedPolygon.push({ x: newX, y: newY });
			}

			shrinkedPolygon.number = polygon.number;

			return shrinkedPolygon;
	}

	createShapeFromEdges(shape, edges, startX, startY) {
			const stack = [{ x: startX, y: startY }];

			let _wG_1 = 0; while ((stack.length > 0) && ++_wG_1 < 20000) {
					const { x, y } = stack.pop();

					for (let i = 0; i < edges.length; i++) {
							const edge = edges[i];
							if (edge.x1 === x && edge.y1 === y) {
									shape.push({ x: edge.x1, y: edge.y1 });
									stack.push({ x: edge.x2, y: edge.y2 });
									edges.splice(i, 1);
									break;
							} else if (edge.x2 === x && edge.y2 === y) {
									shape.push({ x: edge.x2, y: edge.y2 });
									stack.push({ x: edge.x1, y: edge.y1 });
									edges.splice(i, 1);
									break;
							}
					}
			}

			return shape;
	}

	//find neighbors with same number
	findNeighbors(number, index, neighbors) {
    const stack = [{ number, index }];

    let _wG_2 = 0; while ((stack.length > 0) && ++_wG_2 < 20000) {
        const { number, index } = stack.pop();
        const gridItem = this.grid[index];

        if (index < this.grid.length && !gridItem.used && gridItem.number === number) {
            gridItem.used = true; // Mark the grid item as used
            neighbors.push(gridItem);

            // Check left
            if (index % this.itensPerRow !== 0)
                stack.push({ number, index: index - 1 });

            // Check right
            if (index % this.itensPerRow !== this.itensPerRow - 1)
                stack.push({ number, index: index + 1 });

            // Check top
            if (index >= this.itensPerRow)
                stack.push({ number, index: index - this.itensPerRow });

            // Check bottom
            if (index < this.grid.length - this.itensPerRow)
                stack.push({ number, index: index + this.itensPerRow });
        }
    }
	}
}

