var colors = ["#ff8ba6", "#db3b60", "#0b7ca9"];
var colors2;

const GRID_UNITS = 20;
const GRID_SIZE = Math.min(innerWidth, innerHeight) / GRID_UNITS;
var grid, values;
const number_of_types = colors.length;
var itensPerRow, itensPerColumn;

var walkers = [];

function setup() {
	describe("An abstract art piece with colorful shapes that move and change dynamically. It utilizes a grid-based system where each grid cell can have one of several colors. As the program runs, colored shapes evolve across the canvas, creating an ever-changing visual experience.");

	createCanvas(windowWidth, windowHeight);

	strokeWeight(GRID_SIZE/8);
	strokeJoin(ROUND);

	//init colors
	colors.forEach((str, i) => colors[i] = color(str));
	colors2 = colors.map(c => {
		return color(
			c._getRed() * 1.2,
			c._getGreen() * 1.2,
			c._getBlue() * 1.2
		)
	})

	//create grid values
	values = [];
	itensPerColumn = 0;
	for(var y = 0; y < height-2; y += (Math.max(0.001, Math.abs(GRID_SIZE)) || 1)) {
		itensPerColumn++;
		itensPerRow = 0;
		for(var x = 0; x < width-2; x += (Math.max(0.001, Math.abs(GRID_SIZE)) || 1)) {
			itensPerRow++;
			values.push(floor(random(number_of_types)))
		}
	}

	//init walkers
	for(var number = 0; number < number_of_types; number++){
		const x = floor(random(itensPerRow));
		const y = floor(random(itensPerColumn));
		walkers.push({x, y, number, easeX: x, easeY: y})
	}

	updateGrid();
}

function updateGrid(){
	walkers.forEach(w => {
		if(random([true, false]))
			w.x = constrain(w.x + random([-1, 1]), 0, itensPerRow-1);
		else
			w.y = constrain(w.y + random([-1, 1]), 0, itensPerColumn-1);
		values[w.y * itensPerRow + w.x] = w.number;
	})

	grid = new Grid(GRID_SIZE, width-2, height-2, number_of_types, values);

	//shrink polygon
	grid.shapes = grid.shapes.map(shape => grid.shrinkPolygon(shape, GRID_SIZE/4));

	//add colors
	grid.shapes.forEach(shape => {
		if(shape.number >= 0)
			shape.color = colors[shape.number];
			shape.color2 = colors2[shape.number];
	})
}

function draw() {
	background("#fff");

	if(frameCount%10==0)
		updateGrid();

	//draw shapes
	grid.shapes.forEach(shape => {
		if(shape.number >= 0) {
			stroke(shape.color);
			fill(shape.color2);
			beginShape();
			for(let i = 1; i < shape.length + 2; i++){
				const coordP = shape[(i-1)%shape.length]
				const coordC = shape[i%shape.length]
				const coordN = shape[(i+1)%shape.length]
				const coord1X = lerp(coordP.x, coordC.x, 0.8);
				const coord1Y = lerp(coordP.y, coordC.y, 0.8);
				const coord2X = lerp(coordN.x, coordC.x, 0.8);
				const coord2Y = lerp(coordN.y, coordC.y, 0.8);

				curveVertex(coord1X, coord1Y);
				curveVertex(coord2X, coord2Y);
			}
			endShape(CLOSE);
		}
	});

	//draw dots
	noStroke();
	values.forEach((v, index) => {
		var x = index % itensPerRow + 0.5;
		var y = floor(index / itensPerRow) + 0.5;
		fill(colors[v]);
		circle(x * GRID_SIZE, y * GRID_SIZE, GRID_SIZE/6);
	})

	//draw walkers
	noFill();
	walkers.forEach((w, i) => {
		w.easeX += (w.x - w.easeX) * 0.3;
		w.easeY += (w.y - w.easeY) * 0.3;
		stroke(colors[w.number]);
		circle((w.easeX + 0.5) * GRID_SIZE, (w.easeY + 0.5) * GRID_SIZE, GRID_SIZE/2);
	})
}

function mousePressed(){
	const x = floor((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/width*itensPerRow);
	const y = floor((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/height*itensPerColumn);
	walkers.push({x, y, number: floor(random(number_of_types)), easeX: x, easeY: y});
	updateGrid();
}

function keyPressed(){
	updateGrid();
}

